# Minimal writers matching current importer contracts.
write_synthetic_diann <- function(fixture, path) { q <- as.data.frame(fixture$quantity, check.names = FALSE); names(q) <- paste0(names(q), ".d"); raw <- cbind(`Protein.Group` = fixture$meta$ProteinID, `Protein.Ids` = fixture$meta$ProteinID, `Protein.Names` = fixture$meta$ProteinName, Genes = fixture$meta$Gene, q); names(raw) <- c("Protein.Group", "Protein.Ids", "Protein.Names", "Genes", names(q)); data.table::fwrite(raw, path, sep = "\t", na = ""); path }
write_synthetic_spectronaut <- function(fixture, path) { q <- as.data.frame(fixture$quantity, check.names = FALSE); names(q) <- paste0("[", seq_along(q), "] ", colnames(fixture$quantity), ".PG.Quantity"); i <- as.data.frame(ifelse(is.na(fixture$qualitative), NA_real_, 1), check.names = FALSE); names(i) <- paste0("[", seq_along(i), "] ", colnames(fixture$quantity), ".PG.IBAQ"); raw <- cbind(`PG.ProteinGroups` = fixture$meta$ProteinID, `PG.ProteinAccessions` = fixture$meta$ProteinID, `PG.Genes` = fixture$meta$Gene, `PG.ProteinDescriptions` = fixture$meta$ProteinName, `PG.ProteinNames` = fixture$meta$ProteinName, q, i); names(raw) <- c("PG.ProteinGroups", "PG.ProteinAccessions", "PG.Genes", "PG.ProteinDescriptions", "PG.ProteinNames", names(q), names(i)); data.table::fwrite(raw, path, sep = "\t", na = ""); path }
write_synthetic_fragpipe <- function(fixture, path) { q <- as.data.frame(fixture$quantity, check.names = FALSE); names(q) <- paste0(colnames(fixture$quantity), " MaxLFQ Intensity"); s <- as.data.frame(ifelse(is.na(fixture$qualitative), 0, 1), check.names = FALSE); names(s) <- paste0(colnames(fixture$quantity), " Spectral Count"); raw <- cbind(Protein = fixture$meta$ProteinID, `Protein ID` = fixture$meta$ProteinID, `Entry Name` = fixture$meta$ProteinName, Gene = fixture$meta$Gene, q, s); names(raw) <- c("Protein", "Protein ID", "Entry Name", "Gene", names(q), names(s)); data.table::fwrite(raw, path, sep = "\t", na = ""); path }
write_synthetic_peaks_db <- function(fixture, path) { q <- as.data.frame(fixture$quantity, check.names = FALSE); names(q) <- paste0("Area ", colnames(fixture$quantity)); cov <- as.data.frame(ifelse(is.na(fixture$qualitative), 0, 10), check.names = FALSE); names(cov) <- paste0("Coverage(%) ", colnames(fixture$quantity)); raw <- cbind(`Protein Group` = fixture$meta$ProteinID, Top = "TRUE", Accession = fixture$meta$ProteinID, q, cov); names(raw) <- c("Protein Group", "Top", "Accession", names(q), names(cov)); data.table::fwrite(raw, path, sep = "\t", na = ""); path }
write_synthetic_peaks_lfq <- function(fixture, path) { q <- as.data.frame(fixture$quantity, check.names = FALSE); names(q) <- paste0(names(q), " Area"); raw <- cbind(`Protein Group` = fixture$meta$ProteinID, Top = "TRUE", Accession = fixture$meta$ProteinID, q, `Sample Profile (Ratio)` = "1"); names(raw) <- c("Protein Group", "Top", "Accession", names(q), "Sample Profile (Ratio)"); data.table::fwrite(raw, path, sep = "\t", na = ""); path }
write_synthetic_maxquant <- function(fixture, path) { q <- as.data.frame(fixture$quantity, check.names = FALSE); names(q) <- paste0("LFQ intensity ", names(q)); raw <- cbind(`Protein IDs` = fixture$meta$ProteinID, `Majority protein IDs` = fixture$meta$ProteinID, `Fasta headers` = paste0("sp|", fixture$meta$ProteinID, "|", fixture$meta$ProteinName), `Protein names` = fixture$meta$ProteinName, `Gene names` = fixture$meta$Gene, q); names(raw) <- c("Protein IDs", "Majority protein IDs", "Fasta headers", "Protein names", "Gene names", names(q)); data.table::fwrite(raw, path, sep = "\t", na = ""); path }
write_synthetic_standard <- function(fixture, path, sep = ",") { raw <- cbind(FeatureID = rownames(fixture$quantity), as.data.frame(fixture$quantity, check.names = FALSE)); data.table::fwrite(raw, path, sep = sep, na = ""); path }
